struct subject_ops { int (*get)(void *self, int key); };
struct proxy { const struct subject_ops *ops; void *real; long hits; };

static int proxy_get(void *self, int key) {
    struct proxy *p = self;                 /* policy: count accesses */
    p->hits++;
    return p->ops->get(p->real, key);       /* forward unchanged */
}
